function closedArray<T extends string>(
  value: unknown,
  allowed: readonly T[],
  field: string,
  max: number,
): T[] {
  if (!Array.isArray(value) || value.length > max) {
    throw new AiContractError(

);
  }
  return parsed;
}

function subStats(value: unknown): string[] {
  if (!Array.isArray(value) || value.length > 3) {
    throw new AiContractError("sub_stats must contain at most 3 items");
  }
  return value.map((item, index) =>
    inputString(
      item,

,
      1,
      24,
      SAFE_DISPLAY_TEXT,
    ).toUpperCase()
  );
}

function optionalBoolean(value: unknown, field: string): boolean {
  if (typeof value !== "boolean") {
    throw new AiContractError(

);
  }
  return value;
}

function goalDescription(goal: (typeof GOALS)[number]): string {
  switch (goal) {
    case "Lose Weight":
      return "reduce body fat while preserving muscle and natural proportions";
    case "Gain Muscle":
      return "add believable athletic muscle while preserving a natural waist";
    case "Body Recomp":
      return "look leaner and more muscular at the same time";
  }
}

function priorityDescription(priority: (typeof PRIORITIES)[number]): string {
  switch (priority) {
    case "leaner_midsection":
      return "make the waist and midsection visibly leaner";
    case "sharper_definition":
      return "increase visible athletic definition without artificial texture";
    case "upper_body_size":
      return "add balanced size through shoulders, chest, back, and arms";
    case "lower_body_shape":
      return "develop a stronger, balanced lower-body silhouette";
    case "overall_shape":
      return "improve the full-body silhouette in a balanced way";
  }
}

function goalGeometryDescription(
  goal: (typeof GOALS)[number],
  neutralSilhouetteLanguage: boolean,
): string {
  if (neutralSilhouetteLanguage) {
    switch (goal) {
      case "Lose Weight":
        return "make the overall silhouette visibly leaner and the centerline clearly narrower while retaining the source's muscle volume";
      case "Gain Muscle":
        return "make the athletic frame visibly fuller and stronger while retaining the source's body-fat level";
      case "Body Recomp":
        return "make the centerline visibly leaner and the athletic frame visibly fuller at the same time";
    }
  }

  switch (goal) {
    case "Lose Weight":
      return "visibly reduce soft-tissue fullness, narrow the waist and midsection, and reveal the natural contours already supported by the source while keeping muscle volume stable";
    case "Gain Muscle":
      return "visibly increase muscle volume and fullness in the requested visible areas so the outer silhouette expands there while keeping body-fat distribution stable";
    case "Body Recomp":
      return "visibly narrow the waist and reduce soft-tissue fullness while also increasing muscular contour and fullness in the requested visible areas";
  }
}

function transformationProof(
  goal: (typeof GOALS)[number],
  priority: (typeof PRIORITIES)[number],
  neutralSilhouetteLanguage: boolean,
): string {
  let proof = "";
  if (neutralSilhouetteLanguage) {
    switch (goal) {
      case "Lose Weight":
        proof =
          "Dominant proof: a clearly narrower centerline. Supporting proof: proportionally reduced fullness in another visible region while the athletic frame stays coherent.";
        break;
      case "Gain Muscle":
        proof =
          "Dominant proof: a clearly fuller and wider athletic frame. Supporting proof: increased visible fullness in another region while the centerline and body-fat distribution stay coherent.";
        break;
      case "Body Recomp":
        proof =
          "Dominant proof: a clearly narrower centerline. Supporting proof: a simultaneously fuller athletic frame, creating a stronger proportion instead of a uniformly scaled body.";
        break;
    }
  } else {
    switch (goal) {
      case "Lose Weight":
        proof =
          "Dominant proof: the visible waist and torso silhouette are clearly narrower than the source. Supporting proof: at least one other visible region shows proportionally reduced soft-tissue fullness while muscle volume remains consistent.";
        break;
      case "Gain Muscle":
        proof =
          "Dominant proof: the visible athletic frame is clearly fuller and wider in the requested development areas. Supporting proof: at least one other visible region shows increased muscle circumference or fullness while waist size and body-fat distribution remain consistent.";
        break;
      case "Body Recomp":
        proof =
          "Dominant proof: the visible waist and centerline are clearly narrower than the source. Supporting proof: the visible athletic frame or requested muscle areas are simultaneously fuller, creating a stronger proportion instead of a uniformly scaled-down body.";
        break;
    }
  }

  return

;
}

